import random
import string
from typing import List

# Generator for POSIX-like signal name strings for get_sig()
# The goal is to return valid and interesting names that exercise case,
# aliases, numbers, unknowns, and edge cases while remaining mostly valid strings.

# Curated common POSIX signal names (portable core and common extensions)
_COMMON_SIGS: List[str] = [
    # POSIX-required
    "SIGHUP", "SIGINT", "SIGQUIT", "SIGILL", "SIGABRT", "SIGFPE", "SIGKILL",
    "SIGSEGV", "SIGPIPE", "SIGALRM", "SIGTERM", "SIGUSR1", "SIGUSR2",
    "SIGCHLD", "SIGCONT", "SIGSTOP", "SIGTSTP", "SIGTTIN", "SIGTTOU",
    "SIGBUS", "SIGPOLL", "SIGPROF", "SIGSYS", "SIGTRAP", "SIGURG",
    "SIGVTALRM", "SIGXCPU", "SIGXFSZ",
    # Very common but not universal
    "SIGWINCH", "SIGIO", "SIGEMT", "SIGINFO",
]

# Possible nonstandard variants that implementations might accept
_VARIANTS: List[str] = [
    "HUP", "INT", "TERM",  # without SIG prefix
    "sigint", "sigterm", "SigAbrt",  # mixed/other case
    "SIGRTMIN", "SIGRTMAX",  # realtime markers
]

# Strings that are valid C strings but probably unknown
_UNKNOWN_TOKENS: List[str] = [
    "SIGFOO", "SIGBAR", "SIGUNKNOWN", "SIG_", "SIG", "SIG0", "SIG-1",
]

# Numeric accepts: some get_sig implementations also accept numbers as strings
_NUMERIC_TOKENS: List[str] = [
    "0", "1", "2", "9", "11", "15", "19", "64"  # common/edge numbers
]

def _rand_ident(rng: random.Random, min_len: int = 1, max_len: int = 12, upper: bool = True) -> str:
    letters = string.ascii_uppercase if upper else string.ascii_letters
    return ''.join(rng.choice(letters) for _ in range(rng.randint(min_len, max_len)))

def _case_variants(rng: random.Random, s: str) -> str:
    mode = rng.randint(0, 4)
    if mode == 0:
        return s
    if mode == 1:
        return s.lower()
    if mode == 2:
        return s.upper()
    if mode == 3:
        # Random mixed case
        return ''.join(c.upper() if rng.random() < 0.5 else c.lower() for c in s)
    # Capitalize tail only
    if s.startswith('SIG') and len(s) > 3:
        tail = s[3:]
        return 'SIG' + ''.join(c.upper() if rng.random() < 0.6 else c.lower() for c in tail)
    return s

def _build_real_time(rng: random.Random) -> str:
    # Construct forms like SIGRTMIN+N, SIGRTMAX-N, SIGRTMIN
    base = rng.choice(["SIGRTMIN", "SIGRTMAX"])
    op = rng.choice(["", "+", "-"])
    if op == "":
        return base
    # choose a small integer offset; keep within typical Linux range 0..31
    n = rng.randint(0, 31)
    return f"{base}{op}{n}"

def _build_known_like(rng: random.Random) -> str:
    # Choose a known or variant, optionally tweak case
    choice_pool = _COMMON_SIGS + _VARIANTS
    s = rng.choice(choice_pool)
    # Occasionally append whitespace or surrounding spaces that many parsers trim
    if rng.random() < 0.15:
        s = (" " * rng.randint(0, 2)) + s + (" " * rng.randint(0, 2))
    # Occasionally add trailing NUL-equivalent representation is not possible here; keep as plain string
    s = _case_variants(rng, s)
    # Optionally add a newline or tab that some parsers may trim
    if rng.random() < 0.08:
        s += rng.choice(["\n", "\t"])
    return s

def _build_unknown_like(rng: random.Random) -> str:
    if rng.random() < 0.5:
        s = "SIG" + _rand_ident(rng, 1, 10, upper=True)
    else:
        s = rng.choice(_UNKNOWN_TOKENS)
    return _case_variants(rng, s)

def _build_numeric(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(_NUMERIC_TOKENS)
    # build a random small integer as string; bias to typical signal ranges
    if rng.random() < 0.8:
        return str(rng.randint(1, 31))
    return str(rng.randint(32, 127))

def _build_edge(rng: random.Random) -> str:
    # Edge but still valid as C string: empty, spaces, or only SIG
    choice = rng.randint(0, 5)
    if choice == 0:
        return ""  # empty string
    if choice == 1:
        return "SIG"  # prefix only
    if choice == 2:
        return " sigint "  # lower + spaces
    if choice == 3:
        return "\tSIGTERM\n"  # with whitespace around
    if choice == 4:
        return "S\u0130GINT"  # dotted I to test ASCII sensitivity, still valid UTF-8
    return "SİG"  # non-ASCII variant

def _assemble_pool(rng: random.Random) -> List[str]:
    items: List[str] = []
    # Ensure a mix of categories
    items.append(_build_known_like(rng))
    items.append(_build_unknown_like(rng))
    items.append(_build_real_time(rng))
    items.append(_build_numeric(rng))
    items.append(_build_edge(rng))

    # Add a few more random entries from categories
    for _ in range(rng.randint(2, 6)):
        which = rng.random()
        if which < 0.4:
            items.append(_build_known_like(rng))
        elif which < 0.7:
            items.append(_build_unknown_like(rng))
        elif which < 0.9:
            items.append(_build_real_time(rng))
        else:
            items.append(_build_numeric(rng))
    return items

def _choose_and_pack(rng: random.Random, candidates: List[str]) -> bytes:
    # Choose one candidate and encode to bytes. Prefer UTF-8, as most C++ fuzzers treat FUZZ_PARAM_STR as raw bytes.
    s = rng.choice(candidates)
    b = s.encode('utf-8', errors='strict')
    # Ensure we do not exceed the max size and avoid embedded NULs since typical C strings end at NUL
    if len(b) > 4096:
        b = b[:4096]
    return b

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    candidates = _assemble_pool(rng)
    return _choose_and_pack(rng, candidates)
